steps.script:
# Cursor is 25" out; the ghost must be held at the 7" roll, and the hop cost
# the controller will judge the drop with must fit inside it.
var m = tree.root.get_node("Main")
var cc = m.charge_controller
if cc.ghost_visual == null or not is_instance_valid(cc.ghost_visual):
	return false
var start = cc.dragging_model.get("original_position")
var ghost_in = Measurement.px_to_inches((cc.ghost_visual.position - start).length())
var cost = cc._charge_move_cost_inches(cc.ghost_visual.position)
m.set_meta("charge_probe", "cursor=25.00\" ghost=%.3f\" cost=%.3f\" roll=%d\"" % [ghost_in, cost, cc.charge_distance])
return abs(ghost_in - 7.0) <= 0.05 and cost <= float(cc.charge_distance) + 0.02

# Part C (checked here, on this same drop): the over-range drop COMMITS at the
# clamped distance instead of being rejected for exceeding the roll.
var m = tree.root.get_node("Main")
var cc = m.charge_controller
var moved = cc.moved_models.has("m1")
var acc = cc._get_model_charge_accumulated("m1")
m.set_meta("charge_drop_probe", "committed=%s accumulated=%.3f\" roll=%d\"" % [str(moved), acc, cc.charge_distance])
return moved and acc <= float(cc.charge_distance) + 0.02 and acc > 6.5

# Unclamped: the ghost follows the cursor the full 25", well past the roll.
var m = tree.root.get_node("Main")
var cc = m.charge_controller
if cc.ghost_visual == null or not is_instance_valid(cc.ghost_visual):
	return false
var start = cc.dragging_model.get("original_position")
var ghost_in = Measurement.px_to_inches((cc.ghost_visual.position - start).length())
m.set_meta("charge_unclamped_probe", "ghost=%.2f\" roll=%d\"" % [ghost_in, cc.charge_distance])
return ghost_in > 24.0
